INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5671423, 821532, 30214, '<td valign="top">great portrait</td>', 'great portrait', '2009-10-02 12:39:34.000000', NULL, 1),
(5671428, 824840, 97954, '<td valign="top">I really like the feel of this but the dark object in the upper left needs to be removed.</td>', 'I really like the feel of this but the dark object in the upper left needs to be removed.', '2009-10-02 12:42:47.000000', NULL, 1),
(5671448, 825065, 101117, '<td valign="top">Very nice stock shot. Great lighting and colour, and I think the angle works great with the ''emergency'' theme.</td>', 'Very nice stock shot. Great lighting and colour, and I think the angle works great with the ''emergency'' theme.', '2009-10-02 12:54:50.000000', NULL, 1),
(5671454, 821868, 101117, '<td valign="top">Not entirely sure what you''re trying to say here. It''s an interesting picture, though far from technically perfect but it does have a certain appeal.</td>', 'Not entirely sure what you''re trying to say here. It''s an interesting picture, though far from technically perfect but it does have a certain appeal.', '2009-10-02 12:58:28.000000', NULL, 1),
(5671456, 825024, 101117, '<td valign="top">Not really anything going on here that grabs my attention. I''m having a hard time figuring out what the object left of the centre is, I''m guessing a flower though it also looks like some sort of fruit peel.</td>', 'Not really anything going on here that grabs my attention. I''m having a hard time figuring out what the object left of the centre is, I''m guessing a flower though it also looks like some sort of fruit peel.', '2009-10-02 12:59:58.000000', NULL, 1),
(5671459, 824802, 101117, '<td valign="top">The scenery is dramatic and overall it''s well composed, but for some reason the shot doesn''t have an outstanding quality to it. I think it might be the muted colours, the whole scene feels a little flat. Did you shoot this through a long lens perhaps?</td>', 'The scenery is dramatic and overall it''s well composed, but for some reason the shot doesn''t have an outstanding quality to it. I think it might be the muted colours, the whole scene feels a little flat. Did you shoot this through a long lens perhaps?', '2009-10-02 13:01:32.000000', NULL, 1),
(5671460, 824840, 101117, '<td valign="top">Great portrait, and nice processing to go along with it. My only complaint, and I think you''re going to hear a lot of this, is the black object in the upper left hand side, which because of the simplicity of the rest of the shot, really grabs my attention and takes my focus away from the girl.</td>', 'Great portrait, and nice processing to go along with it. My only complaint, and I think you''re going to hear a lot of this, is the black object in the upper left hand side, which because of the simplicity of the rest of the shot, really grabs my attention and takes my focus away from the girl.', '2009-10-02 13:03:41.000000', NULL, 1),
(5671461, 824943, 28322, '<td valign="top">love the concept in here, nice strobing .. 9</td>', 'love the concept in here, nice strobing .. 9', '2009-10-02 13:03:46.000000', NULL, 1),
(5671467, 824327, 101117, '<td valign="top">A lot of the area in this shot feels a touch soft, particularly around the forehead and chin area, but at the same time areas you wouldn''t expect to be are in focus, such as parts of the material, are. I think either your DOF is too shallow, or you have actually missed the focus and artificially compensated in processing but the result isn''t great.</td>', 'A lot of the area in this shot feels a touch soft, particularly around the forehead and chin area, but at the same time areas you wouldn''t expect to be are in focus, such as parts of the material, are. I think either your DOF is too shallow, or you have actually missed the focus and artificially compensated in processing but the result isn''t great.', '2009-10-02 13:07:50.000000', NULL, 1),
(5671470, 821425, 101117, '<td valign="top">Love the expression here! Great capture and colours all round, just a shame the face detail isn''t a little brighter.</td>', 'Love the expression here! Great capture and colours all round, just a shame the face detail isn''t a little brighter.', '2009-10-02 13:09:28.000000', NULL, 1),
(5671471, 824245, 101117, '<td valign="top">Nice shot, like the blurred reflections of the two large buildings. Also like the overall feel of the shot, it''s not over crowded like a lot of skyline shots are.</td>', 'Nice shot, like the blurred reflections of the two large buildings. Also like the overall feel of the shot, it''s not over crowded like a lot of skyline shots are.', '2009-10-02 13:10:24.000000', NULL, 1),
(5671473, 825001, 101117, '<td valign="top">Not really sure what''s going on here, I like the leading lines, but it feels like whatever that is they are leading to has been chopped off, which I just find frustrating.</td>', 'Not really sure what''s going on here, I like the leading lines, but it feels like whatever that is they are leading to has been chopped off, which I just find frustrating.', '2009-10-02 13:12:20.000000', NULL, 1),
(5671474, 824516, 101117, '<td valign="top">Classic sunset scene. Good colours and details right through the shot. I like the way you have managed to keep detail in all areas without blown out sections, I assume multiple exposures and / or grad filters.</td>', 'Classic sunset scene. Good colours and details right through the shot. I like the way you have managed to keep detail in all areas without blown out sections, I assume multiple exposures and / or grad filters.', '2009-10-02 13:14:19.000000', NULL, 1),
(5671478, 824760, 101117, '<td valign="top">I would like to see more of this scene, looks like there''s a lot of potential here, but this shot in particular doesn''t quite capture it I''m afraid.</td>', 'I would like to see more of this scene, looks like there''s a lot of potential here, but this shot in particular doesn''t quite capture it I''m afraid.', '2009-10-02 13:18:09.000000', NULL, 1),
(5671479, 819347, 101117, '<td valign="top">Great timing, crisp, celar and captures the action well.</td>', 'Great timing, crisp, celar and captures the action well.', '2009-10-02 13:19:38.000000', NULL, 1),
(5671481, 824341, 101117, '<td valign="top">Works very well in B&amp;W because of all the interesting details to see. Love all the lines here in all different parts of the image.</td>', 'Works very well in B&W because of all the interesting details to see. Love all the lines here in all different parts of the image.', '2009-10-02 13:20:45.000000', NULL, 1),
(5671483, 821835, 101117, '<td valign="top">Too dark and not enough detail for me. I get that it''s a mood thing, but it''s not working for me.</td>', 'Too dark and not enough detail for me. I get that it''s a mood thing, but it''s not working for me.', '2009-10-02 13:21:29.000000', NULL, 1),
(5671485, 824583, 101117, '<td valign="top">This almost looks like a painting, and I''m not sure if that''s a result of processing or just because it''s such an idyllic scene. Nicely captured!</td>', 'This almost looks like a painting, and I''m not sure if that''s a result of processing or just because it''s such an idyllic scene. Nicely captured!', '2009-10-02 13:22:54.000000', NULL, 1),
(5671487, 824085, 101117, '<td valign="top">He looks smug!</td>', 'He looks smug!', '2009-10-02 13:23:30.000000', NULL, 1),
(5671493, 823199, 101117, '<td valign="top">Not really much of interest in this shot. The building does seem to have potential, perhaps different angles or crop might work.</td>', 'Not really much of interest in this shot. The building does seem to have potential, perhaps different angles or crop might work.', '2009-10-02 13:25:49.000000', NULL, 1),
(5671501, 824870, 101117, '<td valign="top">Nice serene feeling scene. Good lighting and processing, feels almost like a painting.</td>', 'Nice serene feeling scene. Good lighting and processing, feels almost like a painting.', '2009-10-02 13:30:12.000000', NULL, 1),
(5671502, 824285, 28359, '<td valign="top">Great catch, only thing I''d do a little different is move the subject to the left a little more to get him out of the center. Nice DOF</td>', 'Great catch, only thing I''d do a little different is move the subject to the left a little more to get him out of the center. Nice DOF', '2009-10-02 13:30:19.000000', NULL, 1),
(5671507, 825048, 101117, '<td valign="top">Not sure what''s going on here. I''ve stared at it for a while to see if I''m missing something, but while I can make out some forms it''s not anything of interest and I just don''t get it!</td>', 'Not sure what''s going on here. I''ve stared at it for a while to see if I''m missing something, but while I can make out some forms it''s not anything of interest and I just don''t get it!', '2009-10-02 13:33:37.000000', NULL, 1),
(5671510, 824267, 101117, '<td valign="top">No idea what this is, guessing it''s some sort of abstract but I don''t really get it, sorry!</td>', 'No idea what this is, guessing it''s some sort of abstract but I don''t really get it, sorry!', '2009-10-02 13:36:28.000000', NULL, 1),
(5671539, 824802, 108544, '<td valign="top">Love the look on that fuzzy guy! Would have liked to see a more interesting title, to go along with that look. Maybe something along the lines of The Porter, Are you coming? or Trail Guide. I find people tend to appreciate, a well thought out title. Yeah, you will usually get an extra point for it too. If you ever need a suggestion, just send a pm.<br/>Nice shot....</td>', 'Love the look on that fuzzy guy! Would have liked to see a more interesting title, to go along with that look. Maybe something along the lines of The Porter, Are you coming? or Trail Guide. I find people tend to appreciate, a well thought out title. Yeah, you will usually get an extra point for it too. If you ever need a suggestion, just send a pm.Nice shot....', '2009-10-02 13:57:42.000000', NULL, 1),
(5671548, 825052, 108544, '<td valign="top">Great silhouette! 7.5 ah just make it an 8!</td>', 'Great silhouette! 7.5 ah just make it an 8!', '2009-10-02 14:06:12.000000', NULL, 1),
(5671551, 824495, 28882, '<td valign="top">this is bold.   i think it''s well balanced and the two windows are interesting but i''m not loving it. 6 for now</td>', 'this is bold.   i think it''s well balanced and the two windows are interesting but i''m not loving it. 6 for now', '2009-10-02 14:08:55.000000', NULL, 1),
(5671552, 823748, 28882, '<td valign="top">not much for me here.  i do like the look of the fenc and the shallow dof there.</td>', 'not much for me here.  i do like the look of the fenc and the shallow dof there.', '2009-10-02 14:09:57.000000', NULL, 1),
(5671554, 824545, 28882, '<td valign="top">beautiful bird but for a peacock i kinda expect brighter colors.  this seems a bit dark.</td>', 'beautiful bird but for a peacock i kinda expect brighter colors.  this seems a bit dark.', '2009-10-02 14:11:11.000000', NULL, 1),
(5671558, 824658, 28882, '<td valign="top">nice subject with well captured textures in the painted areas.  i love the lighting on it too.  i think though that this is a little too tightly cropped expecially near the bottom. 6</td>', 'nice subject with well captured textures in the painted areas.  i love the lighting on it too.  i think though that this is a little too tightly cropped expecially near the bottom. 6', '2009-10-02 14:13:16.000000', NULL, 1),
(5671559, 824988, 1024, '<td valign="top">I am thrilled to see this photo in the FS as I am planning my first trip to this location in a couple of weeks.  Beautiful location and you have captured it so well.  I will be back later to see who you are :-)</td>', 'I am thrilled to see this photo in the FS as I am planning my first trip to this location in a couple of weeks.  Beautiful location and you have captured it so well.  I will be back later to see who you are :-)', '2009-10-02 14:14:18.000000', NULL, 1),
(5671560, 824895, 108384, '<td valign="top">I love New York City.<br/>Great shot.</td>', 'I love New York City.Great shot.', '2009-10-02 14:15:06.000000', NULL, 1),
(5671567, 824887, 30214, '<td valign="top">gorgeous light!</td>', 'gorgeous light!', '2009-10-02 14:18:03.000000', NULL, 1),
(5671570, 824855, 28882, '<td valign="top">i''m not sure how much softness you intended as i know many people add it so i''m not going to comment on that.  i think the cropping is a bit odd.  my eyes want to go straight to the nose piercing and then just wander around.  i think the rule of thirds would suit this better with the piercing pushed up and right and if possible adding some image at the bottom.  if this hasn''t been cropped then i suggest stepping back a little and include more in the image so you can expirement with different crops.</td>', 'i''m not sure how much softness you intended as i know many people add it so i''m not going to comment on that.  i think the cropping is a bit odd.  my eyes want to go straight to the nose piercing and then just wander around.  i think the rule of thirds would suit this better with the piercing pushed up and right and if possible adding some image at the bottom.  if this hasn''t been cropped then i suggest stepping back a little and include more in the image so you can expirement with different crops.', '2009-10-02 14:19:31.000000', NULL, 1),
(5671572, 824944, 30214, '<td valign="top">the flowers in the background make the whole scene somewhat absurd. Which I like. Interesting photo.</td>', 'the flowers in the background make the whole scene somewhat absurd. Which I like. Interesting photo.', '2009-10-02 14:20:29.000000', NULL, 1),
(5671573, 824884, 108384, '<td valign="top">Fantastic smoke shot.  These never get old.</td>', 'Fantastic smoke shot.  These never get old.', '2009-10-02 14:20:32.000000', NULL, 1),
(5671574, 822234, 30214, '<td valign="top">nice</td>', 'nice', '2009-10-02 14:20:38.000000', NULL, 1),
(5671575, 824160, 28882, '<td valign="top">kind of chaotic and subjectless.   i wonder what colors there were here.  it might be more interesting in color.</td>', 'kind of chaotic and subjectless.   i wonder what colors there were here.  it might be more interesting in color.', '2009-10-02 14:21:17.000000', NULL, 1),
(5671576, 823453, 30214, '<td valign="top">nice capture, but the BW conversion is a bit dull.</td>', 'nice capture, but the BW conversion is a bit dull.', '2009-10-02 14:21:32.000000', NULL, 1),
(5671577, 819829, 30214, '<td valign="top">nice</td>', 'nice', '2009-10-02 14:21:40.000000', NULL, 1),
(5671578, 824943, 108384, '<td valign="top">Very scifi-ish.  I love it.</td>', 'Very scifi-ish.  I love it.', '2009-10-02 14:21:41.000000', NULL, 1),
(5671579, 823293, 30214, '<td valign="top">interesting shot!</td>', 'interesting shot!', '2009-10-02 14:22:28.000000', NULL, 1),
(5671580, 825034, 30214, '<td valign="top">a bit oversaturated, don''t you think?</td>', 'a bit oversaturated, don''t you think?', '2009-10-02 14:23:09.000000', NULL, 1),
(5671581, 824843, 108384, '<td valign="top">Mysterious and dark, and tells a story.  My tied pick for yellow.</td>', 'Mysterious and dark, and tells a story.  My tied pick for yellow.', '2009-10-02 14:23:10.000000', NULL, 1),
(5671582, 824835, 28882, '<td valign="top">this has some nice focus and colors, i like the crop and bokeh.   i think it would be better with the butterfly at a different angle though. 6</td>', 'this has some nice focus and colors, i like the crop and bokeh.   i think it would be better with the butterfly at a different angle though. 6', '2009-10-02 14:23:10.000000', NULL, 1),
(5671583, 819829, 108384, '<td valign="top">Heartwrenching and emotional, my tied pick for yellow.</td>', 'Heartwrenching and emotional, my tied pick for yellow.', '2009-10-02 14:23:44.000000', NULL, 1),
(5671586, 824918, 108384, '<td valign="top">WOW.  Amazing lighting, amazing sky, amazing rock texture.  My pick for the red ribbon.</td>', 'WOW.  Amazing lighting, amazing sky, amazing rock texture.  My pick for the red ribbon.', '2009-10-02 14:24:40.000000', NULL, 1),
(5671588, 825009, 30214, '<td valign="top">interesting shot! (which could also be called "smelly shoes" :))</td>', 'interesting shot! (which could also be called "smelly shoes" :))', '2009-10-02 14:24:53.000000', NULL, 1),
(5671589, 825065, 28882, '<td valign="top">looks like a nice image for an ad.   mmm, canned water.   some really old cans too.  7</td>', 'looks like a nice image for an ad.   mmm, canned water.   some really old cans too.  7', '2009-10-02 14:24:58.000000', NULL, 1),
(5671592, 824231, 30214, '<td valign="top">great scene. I wish there was a tiny bit more light in the lower part (split filter or bracketing would help)</td>', 'great scene. I wish there was a tiny bit more light in the lower part (split filter or bracketing would help)', '2009-10-02 14:25:59.000000', NULL, 1),
(5671596, 824508, 108384, '<td valign="top">Life really is beautiful.<br/>One of my favorite shots here on DPC.  Every time I look at it, I love it more.  Perfect composition, perfect silhouette, perfect light, perfect everything.  My pick for the blue ribbon.</td>', 'Life really is beautiful.One of my favorite shots here on DPC.  Every time I look at it, I love it more.  Perfect composition, perfect silhouette, perfect light, perfect everything.  My pick for the blue ribbon.', '2009-10-02 14:26:57.000000', NULL, 1),
(5671597, 824270, 30214, '<td valign="top">great scene. I feel it would work better in BW or bluish tone.</td>', 'great scene. I feel it would work better in BW or bluish tone.', '2009-10-02 14:27:06.000000', NULL, 1),
(5671598, 825030, 30214, '<td valign="top">another Bear_Music''s self-portrait?!</td>', 'another Bear_Music''s self-portrait?!', '2009-10-02 14:27:42.000000', NULL, 1),
(5671599, 825034, 28882, '<td valign="top">what a beautiful place.  there seems to be some kind of color issue here, most noticeably in the clouds.    i think the crop with the centered horizon is a bit uncomfortable also.</td>', 'what a beautiful place.  there seems to be some kind of color issue here, most noticeably in the clouds.    i think the crop with the centered horizon is a bit uncomfortable also.', '2009-10-02 14:27:49.000000', NULL, 1),
(5671601, 823805, 30214, '<td valign="top">striking scene! (slightly oversaturated in the foreground to my taste)</td>', 'striking scene! (slightly oversaturated in the foreground to my taste)', '2009-10-02 14:28:26.000000', NULL, 1),
(5671602, 824764, 30214, '<td valign="top">wow! I though at first the shot was turned 90 deg... :) beautiful abstract!</td>', 'wow! I though at first the shot was turned 90 deg... :) beautiful abstract!', '2009-10-02 14:29:37.000000', NULL, 1),
(5671605, 823233, 30214, '<td valign="top">Mother Nature at its best</td>', 'Mother Nature at its best', '2009-10-02 14:30:04.000000', NULL, 1),
(5671606, 819757, 30214, '<td valign="top">I like the light, and the background</td>', 'I like the light, and the background', '2009-10-02 14:30:25.000000', NULL, 1),
(5671607, 824097, 30214, '<td valign="top">beautiful light!</td>', 'beautiful light!', '2009-10-02 14:30:35.000000', NULL, 1),
(5671608, 824915, 28882, '<td valign="top">cool props and beautiful models.   are those antlers coming out of her head or is that something in the background?</td>', 'cool props and beautiful models.   are those antlers coming out of her head or is that something in the background?', '2009-10-02 14:30:36.000000', NULL, 1),
(5671611, 824231, 28882, '<td valign="top">very first thing, ok second, the sun was first, second thing to catch my eye was that the rocks to the left came up to the horizon line.  it makes it feel like the rocks were cut off there.   i love the sky and the rocks in the right center area just below the sun.</td>', 'very first thing, ok second, the sun was first, second thing to catch my eye was that the rocks to the left came up to the horizon line.  it makes it feel like the rocks were cut off there.   i love the sky and the rocks in the right center area just below the sun.', '2009-10-02 14:33:10.000000', NULL, 1),
