(5672986, 824556, 101117, '<td valign="top">This is one of the nicer landscape shots I''ve come across this free study. I love the details you have here, and while I initially thought it was a little dark, after sitting looking at it for a while (and turning the brightness on my screen up slightly) I think the dark areas are actually just right for keeping the mood you have here. 10 from me, I really like this!</td>', 'This is one of the nicer landscape shots I''ve come across this free study. I love the details you have here, and while I initially thought it was a little dark, after sitting looking at it for a while (and turning the brightness on my screen up slightly) I think the dark areas are actually just right for keeping the mood you have here. 10 from me, I really like this!', '2009-10-03 12:58:07.000000', NULL, 1),
(5672987, 825040, 100831, '<td valign="top">Nice! Love the pov.</td>', 'Nice! Love the pov.', '2009-10-03 12:58:23.000000', NULL, 1),
