(5673198, 821535, 100393, '<td valign="top">OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award: <br/> <br/>Positives: Sometimes during this comment series I find myself commenting on images that have more than ''just'' niche appeal - this is one of those images. What a brave edit to take this so dark but I really believe it is this boldness which is the key to the success of the image. The compositional elements are fantastic - such drama. The more I look at the image the better it gets.<br/> <br/>Critical stuff: Nothing really, though I worry about the edit to your background.<br/> <br/>Overall: This is a very good image, full of drama - I expect this to do very well.</td>', 'OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award:  Positives: Sometimes during this comment series I find myself commenting on images that have more than ''just'' niche appeal - this is one of those images. What a brave edit to take this so dark but I really believe it is this boldness which is the key to the success of the image. The compositional elements are fantastic - such drama. The more I look at the image the better it gets. Critical stuff: Nothing really, though I worry about the edit to your background. Overall: This is a very good image, full of drama - I expect this to do very well.', '2009-10-03 15:45:54.000000', NULL, 1),
(5673203, 824397, 99412, '<td valign="top">That would make a very nice home for someone who loves to fish.<br/>........(Someone like me of course).<br/>:)<br/>Very nice photo.<br/>7</td>', 'That would make a very nice home for someone who loves to fish.........(Someone like me of course).:)Very nice photo.7', '2009-10-03 15:50:56.000000', NULL, 1),
(5673224, 824447, 110186, '<td valign="top">Very nice picture. Your subject is very pretty!</td>', 'Very nice picture. Your subject is very pretty!', '2009-10-03 15:57:28.000000', NULL, 1),
(5673235, 820057, 100393, '<td valign="top">OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award: <br/> <br/>Positives: I love the colour and the grain in this image and the close crop is pretty effective. I actually quite like the reflection on the forehead too.<br/> <br/>Critical stuff: I''m not sure how well this all hangs together as a concept - the mask, hat and shirt don''t really seem to gel and the elastic / string on the mask really needs cloning away.<br/> <br/>Overall: Although I appreciated seeing such a conceptual image and I think the technicals are well matched - I think an image such as this lives or dies on the details and one or two of those let the image down.</td>', 'OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award:  Positives: I love the colour and the grain in this image and the close crop is pretty effective. I actually quite like the reflection on the forehead too. Critical stuff: I''m not sure how well this all hangs together as a concept - the mask, hat and shirt don''t really seem to gel and the elastic / string on the mask really needs cloning away. Overall: Although I appreciated seeing such a conceptual image and I think the technicals are well matched - I think an image such as this lives or dies on the details and one or two of those let the image down.', '2009-10-03 16:00:08.000000', NULL, 1),
(5673242, 825043, 99412, '<td valign="top">Some photo''s just speak for themselves.<br/>This is one such photo. <br/>I think I hear it saying, give me a ten, so that''s what i''m giving it.<br/>:)<br/>10<br/>It is a beauty.<br/>:)</td>', 'Some photo''s just speak for themselves.This is one such photo. I think I hear it saying, give me a ten, so that''s what i''m giving it.:)10It is a beauty.:)', '2009-10-03 16:03:32.000000', NULL, 1),
(5673247, 821118, 99412, '<td valign="top">Well, it''s a beauty. It has substance. It has character. It has appeal. It says WOW.<br/> <br/>:)<br/>It get''s a 9<br/> <br/>But I must know.....Is this taken in Montana?</td>', 'Well, it''s a beauty. It has substance. It has character. It has appeal. It says WOW. :)It get''s a 9 But I must know.....Is this taken in Montana?', '2009-10-03 16:06:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5673252, 824291, 99412, '<td valign="top">That house would make a great fishing spot during the day.<br/>Just hang your pole out the window and check it for fish occasionally.<br/> <br/>:)<br/>7<br/>Nice,Peaceful, unique photo.</td>', 'That house would make a great fishing spot during the day.Just hang your pole out the window and check it for fish occasionally. :)7Nice,Peaceful, unique photo.', '2009-10-03 16:11:01.000000', NULL, 1),
(5673264, 822011, 100393, '<td valign="top">OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award: <br/> <br/>Positives: Interesting find! But the more interesting thing for me is what you''ve done with the image. I like your framing - you''ve got enough going on around the periphery to keep the eye nicely bounded; the rear 3/4 window bottom right, the sun flare at the bottom and the internal light top left. The slight amount of grain helps too.<br/> <br/>Critical stuff: I like what you''ve done with this but I just not too sure that there is enough intrinsic interest in the scene to hold a viewers attention.<br/> <br/>Overall: An very good edit of a scene which I think isn''t over-endowed with interest.</td>', 'OK, I''m going through the Free Study submissions, purposefully finding those images I think are shot with a less conventional eye - this is one of those images! Thanks for offering something that isn''t just DPC friendly eye-candy (though of course there''s nothing wrong with eye-candy). I''ll be picking one of these images for my Mu (most underrated) award:  Positives: Interesting find! But the more interesting thing for me is what you''ve done with the image. I like your framing - you''ve got enough going on around the periphery to keep the eye nicely bounded; the rear 3/4 window bottom right, the sun flare at the bottom and the internal light top left. The slight amount of grain helps too. Critical stuff: I like what you''ve done with this but I just not too sure that there is enough intrinsic interest in the scene to hold a viewers attention. Overall: An very good edit of a scene which I think isn''t over-endowed with interest.', '2009-10-03 16:28:39.000000', NULL, 1),
