(5674908, 820642, 108620, '<td valign="top">What an expression. Nice shot.</td>', 'What an expression. Nice shot.', '2009-10-04 22:28:05.000000', NULL, 1),
(5674914, 824868, 108620, '<td valign="top">Nice movement and light. Your vantage point puts the viewer in the midst of the action.</td>', 'Nice movement and light. Your vantage point puts the viewer in the midst of the action.', '2009-10-04 22:31:13.000000', NULL, 1),
