(5679270, 823977, 76335, '<td valign="top">Shooting earlier or later in the day might have helped this shot. Too much of the foreground is in the shadows.</td>', 'Shooting earlier or later in the day might have helped this shot. Too much of the foreground is in the shadows.', '2009-10-07 21:22:14.000000', NULL, 1),
(5679271, 823957, 76335, '<td valign="top">Great title!</td>', 'Great title!', '2009-10-07 21:23:07.000000', NULL, 1),
(5679272, 819340, 76335, '<td valign="top">The yellow almost does look like a profile. Good studio work here.</td>', 'The yellow almost does look like a profile. Good studio work here.', '2009-10-07 21:24:07.000000', NULL, 1),
(5679277, 824273, 76335, '<td valign="top">They''ll love it.</td>', 'They''ll love it.', '2009-10-07 21:30:17.000000', NULL, 1),
(5679280, 822950, 76335, '<td valign="top">The colors are a bit too saturated for me.</td>', 'The colors are a bit too saturated for me.', '2009-10-07 21:32:30.000000', NULL, 1),
(5679282, 823826, 76335, '<td valign="top">Wonderfully impressionistic.</td>', 'Wonderfully impressionistic.', '2009-10-07 21:33:10.000000', NULL, 1),
(5679283, 824231, 76335, '<td valign="top">Please level your horizon (!).</td>', 'Please level your horizon (!).', '2009-10-07 21:34:10.000000', NULL, 1),
(5679285, 822011, 76335, '<td valign="top">Wondeful on so many levels.</td>', 'Wondeful on so many levels.', '2009-10-07 21:34:53.000000', NULL, 1),
(5679289, 824906, 76335, '<td valign="top">They look like dancers. Neat.</td>', 'They look like dancers. Neat.', '2009-10-07 21:35:23.000000', NULL, 1),
