(5679293, 824232, 76335, '<td valign="top">Bizarre and unsettling. I sorta like it.</td>', 'Bizarre and unsettling. I sorta like it.', '2009-10-07 21:37:51.000000', NULL, 1),
(5679295, 823029, 76335, '<td valign="top">Good fun. Could be bigger.</td>', 'Good fun. Could be bigger.', '2009-10-07 21:39:09.000000', NULL, 1),
(5679296, 824865, 76335, '<td valign="top">The texture in the building isn''t quite right. Looks like some aliasing -- perhaps too much sharpening?</td>', 'The texture in the building isn''t quite right. Looks like some aliasing -- perhaps too much sharpening?', '2009-10-07 21:40:16.000000', NULL, 1),
(5679298, 822234, 76335, '<td valign="top">Great abstract presentation.</td>', 'Great abstract presentation.', '2009-10-07 21:40:53.000000', NULL, 1),
(5679301, 824766, 57447, '<td valign="top">They''re cute, nice tone and focus.</td>', 'They''re cute, nice tone and focus.', '2009-10-07 21:44:20.000000', NULL, 1),
(5679302, 825035, 57447, '<td valign="top">Great photo, foreground &amp; background.</td>', 'Great photo, foreground & background.', '2009-10-07 21:46:44.000000', NULL, 1),
(5679304, 823279, 57447, '<td valign="top">Wish I was there.</td>', 'Wish I was there.', '2009-10-07 21:47:34.000000', NULL, 1),
